package com.nigson.acceptance.pricing;
import com.nigson.commerce.pricing.*;import com.nigson.commerce.platform.*;import com.nigson.shared.security.ActorAssertion;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import static org.assertj.core.api.Assertions.*;
class ProductPricesTest{
 PricingFixture f;ProductPrices prices;ActorAssertion.Actor actor;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new PricingFixture(jdbc,manager);f.retail();var a=f.marketFixture.adminActor;actor=new ActorAssertion.Actor(a.party(),a.identityIssuer(),a.identitySubject(),null,Set.of("ADMIN"),Set.of(),null);var clock=Clock.systemUTC();prices=new ProductPrices(jdbc,new PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),f.books,f.marketFixture.service,new PlatformStore(jdbc,manager,clock,f.metrics),new AuditWriter(jdbc,clock,f.metrics),clock,manager);}
 @AfterEach void cleanup(){if(f==null)return;f.jdbc.update("DELETE FROM commerce.standard_sku_price WHERE sku_id=?",f.sku);f.jdbc.update("UPDATE commerce.market SET retail_price_book_id=NULL WHERE id=?",f.market);for(UUID id:f.jdbc.query("SELECT id FROM commerce.price_book WHERE created_by=?",(r,n)->r.getObject(1,UUID.class),actor.party().toString())){f.jdbc.update("DELETE FROM commerce.price_entry WHERE price_book_id=?",id);f.jdbc.update("DELETE FROM commerce.outbox_event WHERE aggregate_id=?",id);f.jdbc.update("DELETE FROM commerce.idempotency_record WHERE resource_id=?",id);f.jdbc.update("DELETE FROM commerce.price_book WHERE id=?",id);}f.close();}
 ProductPrices.View input(ProductPrices.View v,String minimum){return new ProductPrices.View(v.marketId(),v.marketVersion(),new ProductPrices.Value(v.retail().bookId(),v.retail().version(),"12.00",v.retail().minimumQuantity(),false),new ProductPrices.Value(v.wholesale().bookId(),v.wholesale().version(),"9.00","10",v.wholesale().legacy()),new ProductPrices.Value(v.distributor().bookId(),v.distributor().version(),"8.00",minimum,v.distributor().legacy()));}
 @Test void oneSavePublishesAllPricesAndReplayCannotDuplicate(){var before=prices.get(actor,f.sku);var request=input(before,"20");var after=prices.save(actor,f.sku,request,"all-prices",UUID.randomUUID());assertThat(after.wholesale().unitAmount()).isEqualTo("9.00");assertThat(after.distributor().minimumQuantity()).isEqualTo("20");assertThat(after.retail().unitAmount()).isEqualTo("12.00");assertThat(f.jdbc.queryForObject("SELECT effective_until FROM commerce.price_book WHERE id=?",java.sql.Timestamp.class,after.retail().bookId())).isEqualTo(f.jdbc.queryForObject("SELECT effective_until FROM commerce.price_book WHERE id=?",java.sql.Timestamp.class,before.retail().bookId()));assertThat(after.wholesale().legacy()).isFalse();assertThat(prices.save(actor,f.sku,request,"all-prices",UUID.randomUUID())).isEqualTo(after);assertThatThrownBy(()->prices.save(actor,f.sku,request,"stale-prices",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");}
 @Test void clearingStandardPriceDoesNotResurrectHistoricalBooks()throws Exception{var saved=prices.save(actor,f.sku,input(prices.get(actor,f.sku),"20"),"initial-clear-test",UUID.randomUUID());var empty=new ProductPrices.Value(saved.wholesale().bookId(),saved.wholesale().version(),null,null,false);var cleared=prices.save(actor,f.sku,new ProductPrices.View(saved.marketId(),saved.marketVersion(),saved.retail(),empty,saved.distributor()),"clear-wholesale",UUID.randomUUID());assertThat(cleared.wholesale().unitAmount()).isNull();assertThat(prices.get(actor,f.sku).wholesale().legacy()).isFalse();try(var in=getClass().getResourceAsStream("/db/changelog/047-bp3-standard-sku-price-rollback.sql")){String sql=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertThatThrownBy(()->f.admin.execute(sql)).satisfies(e->assertThat(((org.springframework.dao.DataAccessException)e).getMostSpecificCause().getMessage()).contains("Populated table commerce.standard_sku_price"));}}
 @Test void invalidLastPriceRollsBackRetailWholesaleAndBindings(){var before=prices.get(actor,f.sku);assertThatThrownBy(()->prices.save(actor,f.sku,input(before,"0"),"invalid-last-price",UUID.randomUUID())).isInstanceOf(RuntimeException.class);assertThat(prices.get(actor,f.sku)).isEqualTo(before);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.standard_sku_price WHERE sku_id=?",Integer.class,f.sku)).isZero();}
}
